  Assert.assertEquals("a./b",CanonicalPathUtils.canonicalize("a./b"));
  Assert.assertEquals("a./.b",CanonicalPathUtils.canonicalize("a./.b"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a//b"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a///b"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a////b"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a/./b"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a/././b"));
  Assert.assertEquals("a/b/c",CanonicalPathUtils.canonicalize("a/./b/./c"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a/./././b"));
  Assert.assertEquals("a/b/",CanonicalPathUtils.canonicalize("a/./././b/./"));
  Assert.assertEquals("a/b",CanonicalPathUtils.canonicalize("a/./././b/."));
  Assert.assertEquals("/b",CanonicalPathUtils.canonicalize("/a/../b"));
