  final byte[] fam=Bytes.toBytes("col");
  final byte[] qf=Bytes.toBytes("umn");
  final byte[] nb=new byte[0];
  KeyValue[] keys={new KeyValue(Bytes.toBytes("aaaaa,\u0000\u0000,2"),fam,qf,2,nb),new KeyValue(Bytes.toBytes("aaaaa,\u0001,3"),fam,qf,3,nb),new KeyValue(Bytes.toBytes("aaaaa,,1"),fam,qf,1,nb),new KeyValue(Bytes.toBytes("aaaaa,\u1000,5"),fam,qf,5,nb),new KeyValue(Bytes.toBytes("aaaaa,a,4"),fam,qf,4,nb),new KeyValue(Bytes.toBytes("a,a,0"),fam,qf,0,nb)};
  for (int i=0; i < keys.length; i++) {
    set.add(keys[i]);
  }
  boolean assertion=false;
  int count=0;
  try {
    for (    KeyValue k : set) {
      assertTrue(count++ == k.getTimestamp());
    }
  }
 catch (  junit.framework.AssertionFailedError e) {
    assertion=true;
  }
  assertTrue(assertion);
  set=new TreeSet<KeyValue>(new KeyValue.MetaComparator());
  for (int i=0; i < keys.length; i++) {
    set.add(keys[i]);
  }
  count=0;
  for (  KeyValue k : set) {
    assertTrue(count++ == k.getTimestamp());
  }
  KeyValue[] rootKeys={new KeyValue(Bytes.toBytes(".META.,aaaaa,\u0000\u0000,0,2"),fam,qf,2,nb),new KeyValue(Bytes.toBytes(".META.,aaaaa,\u0001,0,3"),fam,qf,3,nb),new KeyValue(Bytes.toBytes(".META.,aaaaa,,0,1"),fam,qf,1,nb),new KeyValue(Bytes.toBytes(".META.,aaaaa,\u1000,0,5"),fam,qf,5,nb),new KeyValue(Bytes.toBytes(".META.,aaaaa,a,0,4"),fam,qf,4,nb),new KeyValue(Bytes.toBytes(".META.,,0"),fam,qf,0,nb)};
  set=new TreeSet<KeyValue>(new KeyValue.MetaComparator());
  for (int i=0; i < keys.length; i++) {
    set.add(rootKeys[i]);
  }
  assertion=false;
  count=0;
  try {
    for (    KeyValue k : set) {
      assertTrue(count++ == k.getTimestamp());
    }
  }
 catch (  junit.framework.AssertionFailedError e) {
    assertion=true;
  }
  set=new TreeSet<KeyValue>(new KeyValue.RootComparator());
  for (int i=0; i < keys.length; i++) {
    set.add(rootKeys[i]);
  }
  count=0;
  for (  KeyValue k : set) {
    assertTrue(count++ == k.getTimestamp());
  }
}

@Test public void testGetClosestRowBefore() throws IOException {
  final byte[] tableAname=Bytes.toBytes("testGetClosestRowBefore");
  final byte[] row=Bytes.toBytes("row");
  byte[] firstRow=Bytes.toBytes("ro");
  byte[] beforeFirstRow=Bytes.toBytes("rn");
  byte[] beforeSecondRow=Bytes.toBytes("rov");
  HTable table=TEST_UTIL.createTable(tableAname,new byte[][]{HConstants.CATALOG_FAMILY,Bytes.toBytes("info2")});
  Put put=new Put(firstRow);
  Put put2=new Put(row);
  byte[] zero=new byte[]{0};
  byte[] one=new byte[]{1};
  put.add(HConstants.CATALOG_FAMILY,null,zero);
  put2.add(HConstants.CATALOG_FAMILY,null,one);
  table.put(put);
  table.put(put2);
  Result result=null;
  result=table.getRowOrBefore(beforeFirstRow,HConstants.CATALOG_FAMILY);
  assertTrue(result == null);
  result=table.getRowOrBefore(firstRow,HConstants.CATALOG_FAMILY);
  assertTrue(result.containsColumn(HConstants.CATALOG_FAMILY,null));
  assertTrue(Bytes.equals(result.getValue(HConstants.CATALOG_FAMILY,null),zero));
  result=table.getRowOrBefore(beforeSecondRow,HConstants.CATALOG_FAMILY);
  assertTrue(result.containsColumn(HConstants.CATALOG_FAMILY,null));
  assertTrue(Bytes.equals(result.getValue(HConstants.CATALOG_FAMILY,null),zero));
  result=table.getRowOrBefore(row,HConstants.CATALOG_FAMILY);
  assertTrue(result.containsColumn(HConstants.CATALOG_FAMILY,null));
  assertTrue(Bytes.equals(result.getValue(HConstants.CATALOG_FAMILY,null),one));
  result=table.getRowOrBefore(Bytes.add(row,one),HConstants.CATALOG_FAMILY);
  assertTrue(result.containsColumn(HConstants.CATALOG_FAMILY,null));
  assertTrue(Bytes.equals(result.getValue(HConstants.CATALOG_FAMILY,null),one));
}

